#include <vector>
#include "friends.h"
#include "queue.h"
#include "stack.h"

//==========================================
// GRAPH MODULE (HOA 10: graphs, BFS, DFS)
// The friend network is an undirected graph: a user is a vertex, an accepted friendship is an edge.
// Two representations are built from the same FriendList:
//   adjacency LIST   - for every vertex, the list of its neighbours (small memory, used for traversal)
//   adjacency MATRIX - matrix[a][b] is 1 when a and b are friends (O(1) "are they friends?" check)
// Vertices are numbered 0..n-1. userIds[v] gives the real user id of vertex v.
//
// Used by the "Friend network" screen in screens_discover.h: degrees of separation (BFS),
// friend suggestions (friends of friends), and the size of a friend group (DFS).
//==========================================

struct FriendGraph {
    std::vector<int> userIds;                   // vertex -> user id
    std::vector<std::vector<int>> adj;          // adjacency list
    std::vector<std::vector<char>> matrix;      // adjacency matrix
};

// vertex number of a user id, or -1 when the user has no friendship at all
//--- graphVertexOf --------------------------------------------------------------------------------
// What    : The vertex number of a user id.
// Returns : the vertex, or -1 when the user has no friendship
// Used by : buildFriendGraph, doNetwork (screens.h)
//--------------------------------------------------------------------------------------------------
inline int graphVertexOf(const FriendGraph& g, int userId) {
    for (size_t v = 0; v < g.userIds.size(); v++) {
        if (g.userIds[v] == userId) return (int)v;
    }
    return -1;
}

// builds the graph from the accepted friendships. Pending requests are not edges.
// extraUserId is added as a vertex even without friends (so the logged in user is always a vertex).
//--- buildFriendGraph -----------------------------------------------------------------------------
// What    : Builds the friend graph from the accepted friendships, as an adjacency list and an
//           adjacency matrix. Pending requests are not edges.
// Returns : the graph
// Used by : doNetwork (screens.h), doShowcase (screens.h)
//--------------------------------------------------------------------------------------------------
inline FriendGraph buildFriendGraph(const FriendList& list, int extraUserId = 0) {
    FriendGraph g;
    auto vertexFor = [&g](int userId) {
        int v = graphVertexOf(g, userId);
        if (v == -1) {
            g.userIds.push_back(userId);
            v = (int)g.userIds.size() - 1;
        }
        return v;
    };
    if (extraUserId != 0) vertexFor(extraUserId);
    for (FriendNode* f = list.head; f != nullptr; f = f->next) {
        if (f->accepted) {
            vertexFor(f->fromId);
            vertexFor(f->toId);
        }
    }
    int n = (int)g.userIds.size();
    g.adj.assign((size_t)n, std::vector<int>());
    g.matrix.assign((size_t)n, std::vector<char>((size_t)n, 0));
    for (FriendNode* f = list.head; f != nullptr; f = f->next) {
        if (!f->accepted) continue;
        int a = graphVertexOf(g, f->fromId);
        int b = graphVertexOf(g, f->toId);
        if (a == b || g.matrix[(size_t)a][(size_t)b]) continue;
        g.matrix[(size_t)a][(size_t)b] = 1;
        g.matrix[(size_t)b][(size_t)a] = 1;
        g.adj[(size_t)a].push_back(b);
        g.adj[(size_t)b].push_back(a);
    }
    return g;
}

// matrix lookup, false for vertices that do not exist
//--- graphAreFriends ------------------------------------------------------------------------------
// What    : Looks in the adjacency matrix, O(1).
// Returns : true when the two vertices are friends
// Used by : graphSuggestFriends
//--------------------------------------------------------------------------------------------------
inline bool graphAreFriends(const FriendGraph& g, int a, int b) {
    int n = (int)g.adj.size();
    if (a < 0 || b < 0 || a >= n || b >= n) return false;
    return g.matrix[(size_t)a][(size_t)b] != 0;
}

// Breadth first search from one vertex. Returns the distance (number of friendships) to every vertex,
// -1 for a vertex that cannot be reached. BFS visits the vertices level by level using a queue,
// so the first time it reaches a vertex is the shortest way.
//--- graphBfsDistances ----------------------------------------------------------------------------
// What    : Breadth first search with a queue from one vertex. The first time BFS reaches a vertex
//           is the shortest way.
// Returns : the distance to every vertex, -1 when unreachable
// Used by : doNetwork (screens.h), graphSuggestFriends
//--------------------------------------------------------------------------------------------------
inline std::vector<int> graphBfsDistances(const FriendGraph& g, int start) {
    std::vector<int> dist(g.adj.size(), -1);
    if (start < 0 || start >= (int)g.adj.size()) return dist;
    LinkedQueue<int> line;
    dist[(size_t)start] = 0;
    line.enqueue(start);
    int v;
    while (line.dequeue(v)) {
        for (size_t i = 0; i < g.adj[(size_t)v].size(); i++) {
            int w = g.adj[(size_t)v][i];
            if (dist[(size_t)w] == -1) {
                dist[(size_t)w] = dist[(size_t)v] + 1;
                line.enqueue(w);
            }
        }
    }
    return dist;
}

// Shortest chain of friends from one vertex to another, both ends included. Empty when there is no chain.
//--- graphShortestPath ----------------------------------------------------------------------------
// What    : Shortest chain of friends between two vertices (BFS that remembers each vertex's
//           parent).
// Returns : the vertices from start to end, empty when there is no chain
// Used by : doNetwork (screens.h)
//--------------------------------------------------------------------------------------------------
inline std::vector<int> graphShortestPath(const FriendGraph& g, int from, int to) {
    std::vector<int> path;
    int n = (int)g.adj.size();
    if (from < 0 || to < 0 || from >= n || to >= n) return path;
    std::vector<int> parent((size_t)n, -1);
    std::vector<char> seen((size_t)n, 0);
    LinkedQueue<int> line;
    seen[(size_t)from] = 1;
    line.enqueue(from);
    int v;
    while (line.dequeue(v)) {
        if (v == to) break;
        for (size_t i = 0; i < g.adj[(size_t)v].size(); i++) {
            int w = g.adj[(size_t)v][i];
            if (!seen[(size_t)w]) {
                seen[(size_t)w] = 1;
                parent[(size_t)w] = v;
                line.enqueue(w);
            }
        }
    }
    if (!seen[(size_t)to]) return path;
    for (int cur = to; cur != -1; cur = parent[(size_t)cur]) path.push_back(cur);
    for (size_t i = 0, j = path.size() - 1; i < j; i++, j--) {      // the chain was built backwards
        int temp = path[i];
        path[i] = path[j];
        path[j] = temp;
    }
    return path;
}

// Depth first search with an explicit stack. Returns every vertex that can be reached from start,
// in the order DFS visits them. The size of that list is the size of the friend group.
//--- graphDfsOrder --------------------------------------------------------------------------------
// What    : Depth first search with an explicit stack. The size of the result is the size of the
//           friend group.
// Returns : the reachable vertices in visiting order
// Used by : doNetwork (screens.h), doShowcase (screens.h)
//--------------------------------------------------------------------------------------------------
inline std::vector<int> graphDfsOrder(const FriendGraph& g, int start) {
    std::vector<int> order;
    if (start < 0 || start >= (int)g.adj.size()) return order;
    std::vector<char> seen(g.adj.size(), 0);
    ArrayStack<int> pending;
    pending.push(start);
    int v;
    while (pending.pop(v)) {
        if (seen[(size_t)v]) continue;
        seen[(size_t)v] = 1;
        order.push_back(v);
        // pushed in reverse so the first neighbour is visited first
        for (size_t i = g.adj[(size_t)v].size(); i > 0; i--) {
            int w = g.adj[(size_t)v][i - 1];
            if (!seen[(size_t)w]) pending.push(w);
        }
    }
    return order;
}

// A suggestion = a user who is NOT yet a friend, with how many friends they share with the user.
struct FriendSuggestion {
    int userId = 0;
    int mutualFriends = 0;
};

// friends of friends (distance exactly 2), the most mutual friends first.
// The ordering uses insertion sort so that equal users keep their vertex order.
//--- graphSuggestFriends --------------------------------------------------------------------------
// What    : Friends of friends (distance exactly 2) with the number of mutual friends, most mutual
//           friends first (insertion sort keeps equal users in order).
// Returns : the suggestions
// Used by : doNetwork (screens.h)
//--------------------------------------------------------------------------------------------------
inline std::vector<FriendSuggestion> graphSuggestFriends(const FriendGraph& g, int start) {
    std::vector<FriendSuggestion> out;
    if (start < 0 || start >= (int)g.adj.size()) return out;
    std::vector<int> dist = graphBfsDistances(g, start);
    for (size_t v = 0; v < g.adj.size(); v++) {
        if (dist[v] != 2) continue;
        FriendSuggestion s;
        s.userId = g.userIds[v];
        for (size_t i = 0; i < g.adj[v].size(); i++) {
            if (graphAreFriends(g, start, g.adj[v][i])) s.mutualFriends++;
        }
        out.push_back(s);
    }
    for (size_t i = 1; i < out.size(); i++) {
        FriendSuggestion cur = out[i];
        size_t j = i;
        while (j > 0 && cur.mutualFriends > out[j - 1].mutualFriends) {
            out[j] = out[j - 1];
            j--;
        }
        out[j] = cur;
    }
    return out;
}

#endif //STEAM_GRAPH_H
